// Approximate body with capsule-like shape using spheres and cylinder
module capsule(d, h) {
    translate([0, 0, -h/2]) {
        sphere(d=d/2);
        cylinder(d=d, h=h);
        translate([0, 0, h]) sphere(d=d/2);
    }
}

// Main alpaca model
module alpaca() {
    color("LightGrey") {
        // Body
        translate([0, 1, 0])
        rotate([90, 0, 0])
        capsule(2, 2);

        // Neck
        translate([0, 2.5, 0])
        rotate([45, 0, 0])
        rotate([90, 0, 0])
        capsule(1.2, 1.5);

        // Head
        translate([0, 3.8, 0.5])
        sphere(r=0.7);

        // Legs
        leg_positions = [
            [-0.6, 0.2, -0.8],
            [0.6, 0.2, -0.8],
            [-0.6, 0.2, 0.8],
            [0.6, 0.2, 0.8]
        ];

        for(pos = leg_positions) {
            translate(pos)
            cylinder(h=1.5, r1=0.2, r2=0.2, center=true);
        }
    }
}

