    color([1, 0, 0]) // 0xFF0000
    cylinder(h = 0.3, r1 = 0.01, r2 = 0.01, center = true);
}

// Complete snake assembly
module snake() {
    segment_count = 12;
    segment_length = 0.8;

    // Body segments
    for (i = [0:segment_count-1]) {
        radius = i == 0 ? 0.15 : (i == segment_count - 1 ? 0.05 : 0.2 - (i * 0.01));
        translate([0, -i * segment_length, 0])
        body_segment(radius, segment_length, i % 2);
    }

    // Head
    translate([0, segment_length, 0])
    head();

    // Eyes
    translate([0, segment_length, 0]) {
        translate([0.1, 0.1, 0.15])
        eye();
        translate([-0.1, 0.1, 0.15])
        eye();
    }

    // Tongue
    translate([0, segment_length, 0]) {
        translate([0.05, 0, 0.25])
        rotate([30, 0, 0])
        tongue_segment();
        translate([-0.05, 0, 0.25])
        rotate([30, 0, 0])
        tongue_segment();
    }
}

