$fn = 32;

module caterpillar() {
    body_segments = 5;
    segment_radius = 0.8;
    segment_length = 1.5;
    head_radius = segment_radius * 1.2;

    // Body segments (green)
    for (i = [0:body_segments-1]) {
        x_pos = i * (segment_length + 0.2);

        // Body segment capsule (rotated 90° around Z)
        translate([x_pos, 0, 0])
        rotate([0, 90, 0])
        cylinder(h=segment_length, r1=segment_radius, r2=segment_radius, center=true);

        // Legs (dark green)
        create_legs(x_pos, segment_radius);
    }

    // Head (dark green sphere)
    head_x = (body_segments - 1) * (segment_length + 0.2) + segment_length / 2 + head_radius;
    translate([head_x, 0, 0])
    sphere(r=head_radius);

    // Antennas (dark green)
    antenna_x = head_x + head_radius * 0.8;
    antenna_y = head_radius * 0.8;

    // First antenna
    translate([antenna_x, antenna_y, head_radius * 0.8])
    rotate([45, 0, 0])
    cylinder(h=1.5, r1=0.1, r2=0.05, center=false);

    // Second antenna
    translate([antenna_x, antenna_y, -head_radius * 0.8])
    rotate([45, 0, 0])
    cylinder(h=1.5, r1=0.1, r2=0.05, center=false);
}

module create_legs(x_pos, radius) {
    for (i = [0:2]) {
        z_pos = -radius * 0.6 + i * radius * 0.6;
        translate([x_pos, -radius - 0.5, z_pos])
        rotate([30, 0, 0])
        cylinder(h=1, r1=0.15, r2=0.1, center=false);
    }
}

