    // Six legs
    for (i = [0:5]) {
        angle = (i / 6) * 360;
        radius = 0.25;
        x_pos = cos(angle) * radius;
        z_pos = sin(angle) * radius;
        y_pos = -0.4 + (i % 2) * 0.1;

        leg([x_pos, y_pos, z_pos], angle);
    }
}

