    theta = rands(0, 360, 1)[0];
    radius = 0.95;

    x = radius * sin(phi) * cos(theta);
    y = radius * cos(phi);
    z = radius * sin(phi) * sin(theta);

    translate([x, y, z])
    rotate([0, atan2(z, x), atan2(sqrt(x*x + z*z), y) + 90])
    createSpine();
}

