    rotate([45, 0, -45])
    cylinder(h = 0.6, r1 = 0.3, r2 = 0.1, $fn = 8);

    // Right pectoral fin
    translate([-1.2, 0, 0.5])
    rotate([45, 0, 45])
    cylinder(h = 0.6, r1 = 0.3, r2 = 0.1, $fn = 8);

    // Eye
