module createKookaburra() {
    // Body (main part)
    rotate([90, 0, 0])
        capsule(1, 2, 4);

    // Head
    translate([0, 0, 1.5])
        sphere(r=0.8);

    // Beak (long and pointed)
    translate([0, 0, 2.2])
        rotate([90, 0, 0])
            cylinder(h=1.5, r1=0.2, r2=0.2, center=true);

    // Crest feathers on head
    translate([0, 0.8, 1.5])
        rotate([180, 0, 0])
            cylinder(h=0.8, r1=0.3, r2=0);

    // Eyes
    translate([0.3, 0.2, 2])
        sphere(r=0.15);
    translate([-0.3, 0.2, 2])
        sphere(r=0.15);

    // Wings
    translate([1.2, 0, 0])
        rotate([0, 0, 60])
            capsule(0.3, 1.2, 4);
    translate([-1.2, 0, 0])
        rotate([0, 0, -60])
            capsule(0.3, 1.2, 4);

    // Tail
    translate([0, 0, -1.8])
        rotate([30, 0, 0])
            cube([1, 0.1, 1.5], center=true);

    // Legs
    translate([0.4, -1.4, -0.5])
        rotate([30, 0, 0])
            cylinder(h=0.8, r=0.08, center=true);
    translate([-0.4, -1.4, -0.5])
        rotate([30, 0, 0])
            cylinder(h=0.8, r=0.08, center=true);
}

module capsule(radius, height, segments) {
    hull() {
        sphere(r=radius);
        translate([0, 0, height])
            sphere(r=radius);
    }
}

