$fn = 32;

module createKrill() {
    // Body: CapsuleGeometry(0.3, 1.2, 4, 8) - color: 0xFF8C00
    translate([0, 0, 0]) {
        hull() {
            sphere(d = 0.6);
            translate([0, -1.2, 0]) sphere(d = 0.6);
        }
    }

    // Eyes: SphereGeometry(0.08, 16, 16) - color: 0x000000
    translate([0.2, 0.4, 0.15]) sphere(d = 0.16);
    translate([-0.2, 0.4, 0.15]) sphere(d = 0.16);

    // Legs: 10 legs - CylinderGeometry(0.02, 0.02, 0.4, 8) - color: 0xFF6B00
    for (i = [0:9]) {
        y_pos = -0.6 + i * 0.12;
        x_pos = (i % 2 == 0) ? 0.2 : -0.2;
        rot_z = (i % 2 == 0) ? -0.3 : 0.3;

        translate([x_pos, y_pos, 0])
        rotate([0, 0, rot_z])
        cylinder(h = 0.4, d1 = 0.04, d2 = 0.04, center = true);
    }

    // Tail: ConeGeometry(0.2, 0.6, 8) - color: 0xFF8C00
    translate([0, -1.1, 0])
    rotate([90, 0, 0])
    cylinder(h = 0.6, d1 = 0.4, d2 = 0);

    // Antennae: CylinderGeometry(0.01, 0.01, 0.8, 8) - color: 0xFF6B00
    translate([0.1, 0.6, 0])
    rotate([0, 0, -0.4])
    cylinder(h = 0.8, d1 = 0.02, d2 = 0.02, center = true);

    translate([-0.1, 0.6, 0])
    rotate([0, 0, 0.4])
    cylinder(h = 0.8, d1 = 0.02, d2 = 0.02, center = true);
}

// Create the krill
createKrill();

