    translate([0, -1.6, 0])
    cube([0.4, 0.4, 0.3], center=true);
}

module tail_segment2() {
    color("#ff6b6b")
    translate([0, -1.9, 0])
    cube([0.35, 0.35, 0.3], center=true);
}

module tail_fin() {
    color("#ff6b6b")
    translate([0, -2.1, 0])
    rotate([180, 0, 0])
    cylinder(h=0.4, r1=0.2, r2=0);
}

module head() {
    color("#ff6b6b")
    translate([0, 0.8, 0])
    scale([1.2, 0.7, 0.8])
    sphere(r=0.5);
}

module eye(pos) {
    color("black")
    translate(pos)
    sphere(r=0.08);
}

module claw_segment(length, r1, r2, rot_z, pos_x, pos_y) {
    rotate([0, 0, rot_z])
    translate([pos_x, pos_y, 0])
    rotate([90, 0, 0])
    cylinder(h=length, r1=r1, r2=r2);
}

module pincer(rot_z, pos_x, pos_y) {
    rotate([0, 0, rot_z])
    translate([pos_x, pos_y, 0])
    rotate([90, 0, 0])
    cylinder(h=0.3, r1=0.06, r2=0);
}

module claw(side) {
    color("#e63946") {
        claw_segment(0.8, 0.15, 0.1, side * 30, side * 0.8, 0.5);
        claw_segment(0.6, 0.12, 0.08, side * 45, side * 1.2, 0.3);
        pincer(side * 60, side * 1.5, 0.2);
        pincer(-side * 60, side * 1.5, 0.2);
    }
}

module legs() {
    color("#e63946") {
        for (i = [0:5]) {
            translate([(i - 2.5) * 0.3, -0.4, 0.3])
            rotate([45, 0, 0])
            cylinder(h=0.4, r1=0.05, r2=0.03);

            translate([(i - 2.5) * 0.3, -0.4, -0.3])
            rotate([-45, 0, 0])
            cylinder(h=0.4, r1=0.05, r2=0.03);
        }
    }
}

module antenna(pos_z, rot_z) {
    color("#e63946")
    translate([0.3, 1.0, pos_z])
    rotate([0, 0, rot_z])
    rotate([90, 0, 0])
    cylinder(h=1.2, r1=0.02, r2=0.01);
}

union() {
    body();
    tail_base();
    tail_segment1();
    tail_segment2();
    tail_fin();
    head();
    eye([0.4, 1.0, 0.4]);
    eye([0.4, 1.0, -0.4]);
    claw(1);
    claw(-1);
    legs();
    antenna(0.2, -22.5);
    antenna(-0.2, 22.5);
}

