    for (i = [0:5]) {
        angle = i * 60;
        translate([cos(angle) * 0.15, sin(angle) * 0.15, -0.1])
        rotate([90, 0, angle])
        cylinder(h = 0.4, r1 = 0.005, r2 = 0.01, center = true);
