module octopus() {
    // Main body (sphere)
    color([0.333, 0.2, 0.533]) // #553388
    sphere(r=1);

    // Head (slightly elongated sphere)
    color([0.333, 0.2, 0.533]) // #553388
    translate([0, 0.5, 0])
    scale([1, 1.2, 1])
    sphere(r=0.8);

    // Eyes (two spheres)
    color([1, 1, 1]) // white
    translate([-0.4, 0.7, 0.6])
    sphere(r=0.2);

    color([1, 1, 1]) // white
    translate([0.4, 0.7, 0.6])
    sphere(r=0.2);

    // Pupils (small black spheres)
    color([0, 0, 0]) // black
    translate([-0.4, 0.7, 0.75])
    sphere(r=0.08);

    color([0, 0, 0]) // black
    translate([0.4, 0.7, 0.75])
    sphere(r=0.08);

    // Tentacles (8 cylinders with slight curve)
    color([0.267, 0.133, 0.4]) // #442266
    for (i = [0:7]) {
        angle = i * 45;
        scale_factor = 1 + sin(angle) * 0.2;

        translate([cos(angle) * 0.8, -1.2, sin(angle) * 0.8])
        rotate([90, 0, angle])
        scale([1, scale_factor, 1])
        cylinder(h=1.5, r1=0.25, r2=0.15, center=false);
    }
}

