// Tail feathers (green eye shapes)
for (i = [0:4]) {
    angle = (i / 4) * 180 - 90;
    radius = 3;

    // Feather stem (green cylinder)
    x_pos = cos(angle) * radius;
    z_pos = sin(angle) * radius - 1;
    translate([x_pos, 1.5, z_pos]) {
        rotate([90, 0, angle]) {
            cylinder(h=2, r=0.05, $fn=8);
            // Color: 0x00cc66 (green)
        }
    }

    // Feather eye (blue torus)
    eye_x = cos(angle) * (radius + 1.5);
    eye_z = sin(angle) * (radius + 1.5) - 1;
    translate([eye_x, 1.5, eye_z]) {
        rotate([90, 0, 0]) {
            rotate_extrude($fn=32) {
                translate([0.4, 0, 0]) {
                    circle(r=0.1, $fn=16);
                }
            }
            // Color: 0x0066ff (blue)
        }
    }

    // Eye center (black sphere)
    translate([eye_x, 1.51, eye_z]) {
        sphere(r=0.15, $fn=16);
        // Color: 0x000000 (black)
    }
}

