module half_sphere(radius=1) {
    difference() {
        sphere(r=radius, $fn=32);
        translate([0, 0, -radius])
            cube(size=radius*2, center=true);
    }
}

module pelican() {
    // Body (white ellipsoid)
    translate([0, 0.5, 0])
    scale([1.5, 0.8, 1])
        half_sphere(radius=1);

    // Head (smaller sphere)
    translate([1.2, 0.8, 0])
        sphere(r=0.5, $fn=32);

    // Beak (long yellow cone)
    translate([2.2, 0.8, 0])
    rotate([0, 90, 0])
        cylinder(h=1.5, r1=0.3, r2=0, $fn=32);

    // Lower beak pouch (half cylinder)
    translate([2.6, 0.6, 0])
    rotate([90, 0, 90])
    difference() {
        cylinder(h=0.8, r=0.3, $fn=32);
        translate([0, -0.3, -0.1])
            cube([0.6, 0.6, 1], center=false);
    }

    // Wings (flattened cylinders)
    // Left wing
    translate([-0.5, 0.8, 0.8])
    rotate([-45, 0, 0])
    rotate([0, 90, 0])
        cylinder(h=1.5, r1=0.4, r2=0.2, $fn=32);

    // Right wing  
    translate([-0.5, 0.8, -0.8])
    rotate([45, 0, 0])
    rotate([0, 90, 0])
        cylinder(h=1.5, r1=0.4, r2=0.2, $fn=32);

    // Legs (thin cylinders)
    // Left leg
    translate([-0.3, -0.4, 0.3])
        cylinder(h=0.8, r=0.05, $fn=8);

    // Right leg
    translate([-0.3, -0.4, -0.3])
        cylinder(h=0.8, r=0.05, $fn=8);
}

module ground() {
