// Flipper (capsule approximated)
module flipper(length=1.2, radius=0.3) {
    // color: 0x222222 (very dark gray)
    translate([0, 0, length/2]) sphere(r=radius);
    cylinder(h=length, r=radius, center=true);
    translate([0, 0, -length/2]) sphere(r=radius);
