module eye() {
    // color: 0x000000 (black)
    sphere(r=0.15);
}

// Whisker
module whisker(i) {
    // color: 0xFFFFFF (white)
    x_offset = i * 0.15;
    x_end = i * 0.3;
    hull() {
        translate([x_offset, 0.3, 1.2]) sphere(r=0.03);
        translate([x_end, 0.1, 1.6]) sphere(r=0.03);
    }
}

// Complete seal assembly
module seal() {
    // Main body (rotated 90 degrees around X)
    rotate([90, 0, 0]) seal_body();

    // Head
    translate([0, 2.5, 0]) {
        seal_head();

        // Nose
        translate([0, 0, 1.8]) seal_nose();

        // Eyes
        translate([-0.3, 0.5, 0.8]) eye();
        translate([0.3, 0.5, 0.8]) eye();

        // Whiskers
        for(i = [-2:2]) {
            whisker(i);
        }
    }

    // Front flippers
    translate([-1.2, 0, 1.5]) rotate([0, 0, 45]) flipper();
    translate([1.2, 0, 1.5]) rotate([0, 0, -45]) flipper();

    // Rear flippers
    translate([-0.8, 0, -2]) rotate([0, 0, -30]) rear_flipper();
    translate([0.8, 0, -2]) rotate([0, 0, 30]) rear_flipper();
}

