module createSpider() {
    // Body (thorax + abdomen)
    sphere(r = 1);

    // Head
    translate([0.8, 0, 0])
    sphere(r = 0.6);

    // Legs (8 legs)
    positions = [
        [1, 0, 0.5], [1, 0, -0.5],    // Front legs
        [0.5, 0, 0.7], [0.5, 0, -0.7], // Middle front
        [-0.5, 0, 0.7], [-0.5, 0, -0.7], // Middle back
        [-1, 0, 0.5], [-1, 0, -0.5]    // Back legs
    ];

    for (i = [0:7]) {
        pos = positions[i];
        x_rot = i < 4 ? -0.3 : 0.3;
        z_rot = i % 2 == 0 ? 0.5 : -0.5;

        translate([pos[0], pos[1], pos[2]])
        rotate([x_rot, 0, z_rot])
        cylinder(h = 3, r1 = 0.08, r2 = 0.05, center = true);
    }

    // Eyes
    translate([1.3, 0.2, 0.3])
    sphere(r = 0.15);

    translate([1.3, 0.2, -0.3])
    sphere(r = 0.15);
}

