module createStork() {
    // Body (white sphere)
    translate([0, 1.5, 0])
    sphere(1);

    // Head (smaller white sphere)
    translate([0.8, 2.2, 0])
    sphere(0.5);

    // Beak (long orange cone)
    translate([1.4, 2.2, 0])
    rotate([0, 0, 90])
    cylinder(h=1, r1=0.1, r2=0.1, center=false);

    // Legs (thin black cylinders)
    translate([-0.3, 0, 0.2])
    cylinder(h=2, r=0.05, center=false);

    translate([0.3, 0, 0.2])
    cylinder(h=2, r=0.05, center=false);

    // Wings (flattened cylinders)
    translate([-0.8, 1.5, 0])
    rotate([0, 0, 90])
    scale([1, 0.0625, 1])
    cylinder(h=0.8, r=0.8, center=true);

    translate([0.8, 1.5, 0])
    rotate([0, 0, -90])
    scale([1, 0.0625, 1])
    cylinder(h=0.8, r=0.8, center=true);
}

rotate([0, 0, $t * 360])
createStork();

