// Complete sturgeon assembly
module sturgeon() {
    // Main body
    color([0.545, 0.490, 0.420]) // #8B7D6B
    body();

    // Head
    color([0.420, 0.365, 0.294]) // #6B5D4B
    head();

    // Tail
    color([0.545, 0.490, 0.420]) // #8B7D6B
    tail();

    // Dorsal fin
    color([0.420, 0.365, 0.294]) // #6B5D4B
    dorsal_fin();

    // Left pectoral fin
    color([0.420, 0.365, 0.294]) // #6B5D4B
    translate([-1, 0, 0.8])
    rotate([-45, 0, -90])
    fin();

    // Right pectoral fin
    color([0.420, 0.365, 0.294]) // #6B5D4B
    translate([-1, 0, -0.8])
    rotate([45, 0, -90])
    fin();

    // Rostrum
    color([0.353, 0.294, 0.227]) // #5A4B3A
    rostrum();
}

// Render the scene
sturgeon();

