// Body material: color #333333, roughness 0.8
// Leg material: color #222222, roughness 0.9

module createTarantula() {
    union() {
        // Main body (cephalothorax)
        translate([0, 1, 0])
        sphere(r=1.2, $fn=32);

        // Abdomen
        translate([0, 0.8, -1.2])
        scale([1, 0.8, 1.2])
        sphere(r=1.5, $fn=32);

        // Head/eyes area
        translate([0, 1.2, 1])
        sphere(r=0.8, $fn=32);

        // Legs (8 legs total)
        // Right front legs
        translate([1.2, 0, 0.8])
        rotate([30, 0, 0])
        cylinder(h=3, r1=0.15, r2=0.1, $fn=16);

        translate([1.2, 0, -0.8])
        rotate([-30, 0, 0])
        cylinder(h=3, r1=0.15, r2=0.1, $fn=16);

        // Left front legs
        translate([-1.2, 0, 0.8])
        rotate([30, 0, 180])
        cylinder(h=3, r1=0.15, r2=0.1, $fn=16);

        translate([-1.2, 0, -0.8])
        rotate([-30, 0, 180])
        cylinder(h=3, r1=0.15, r2=0.1, $fn=16);

        // Right back legs
        translate([1.5, 0, 0.4])
        rotate([45, 0, 0])
        cylinder(h=3, r1=0.15, r2=0.1, $fn=16);

        translate([1.5, 0, -0.4])
        rotate([-45, 0, 0])
        cylinder(h=3, r1=0.15, r2=0.1, $fn=16);

        // Left back legs
        translate([-1.5, 0, 0.4])
        rotate([45, 0, 180])
        cylinder(h=3, r1=0.15, r2=0.1, $fn=16);

        translate([-1.5, 0, -0.4])
        rotate([-45, 0, 180])
        cylinder(h=3, r1=0.15, r2=0.1, $fn=16);

        // Pedipalps (front appendages)
        translate([0.6, 0.5, 1.8])
        rotate([60, 0, 0])
        cylinder(h=2, r1=0.12, r2=0.08, $fn=16);

        translate([-0.6, 0.5, 1.8])
        rotate([60, 180, 0])
        cylinder(h=2, r1=0.12, r2=0.08, $fn=16);
    }
}

