module createTern() {
    // Body - white oval
    scale([2, 1, 1]) 
    difference() {
        sphere(r=0.5);
        translate([0, -0.5, 0])
        cube([1, 1, 1], center=true);
    }

    // Head - white sphere
    translate([1, 0.1, 0])
    sphere(r=0.3);

    // Beak - orange cone
    translate([1.45, 0.1, 0])
    rotate([0, 90, 0])
    cylinder(h=0.4, r1=0.08, r2=0.08);

    // Wings - white elongated boxes
    // Left wing
    translate([0.2, 0, 0.5])
    rotate([45, 0, 0])
    scale([1.5, 0.1, 0.8])
    cube(1, center=true);

    // Right wing
    translate([0.2, 0, -0.5])
    rotate([-45, 0, 0])
    scale([1.5, 0.1, 0.8])
    cube(1, center=true);

    // Tail - white wedge (4-sided pyramid)
    translate([-1.2, 0, 0])
    rotate([90, 0, 0])
    cylinder(h=0.6, r1=0.3, r2=0, $fn=4);

    // Legs - thin orange cylinders
    // Left leg
    translate([-0.5, -0.7, 0.2])
    cylinder(h=0.4, r=0.02, center=true);

    // Right leg
    translate([-0.5, -0.7, -0.2])
    cylinder(h=0.4, r=0.02, center=true);
}

// Render the tern
createTern();

